// Independent auditor boundary, bundle, startup, migration and public-clock probe for PLAY-04.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { boundaryContext, checkSource } from './scripts/check-boundaries.mjs';
import { client } from './packages/db/dist/index.js';
import { createHttpService } from './packages/service-runtime/dist/index.js';
import { parseClockProjection, parseClockPolicy, decodeLive3ClientFrame, IMPLEMENTED_PROTOCOL_RANGE } from './packages/contracts/dist/index.js';

const MAIN = '775994a';
const sha = b => createHash('sha256').update(b).digest('hex');
const git = (...a) => execFileSync('git', a).toString();
const ctx = boundaryContext(process.cwd());
const owner = name => ctx.owners.find(o => o.name === name);
const browserOwners = ctx.owners.filter(o => ['browser', 'public'].includes(o.scope));
assert.deepEqual(browserOwners.map(o => o.name).sort(), ['@lorcana/contracts', '@lorcana/design-system', '@lorcana/engine-lab', '@lorcana/match-client', '@lorcana/presentation', '@lorcana/web']);
const rel = (from, to) => { const a = from.split('/'), b = to.split('/'); let i = 0; while (a[i] === b[i]) i++; return '../'.repeat(a.length - i) + b.slice(i).join('/'); };
const privateTargets = ['@lorcana/engine-adapter', '@lorcana/match-service', '@lorcana/db', '@lorcana/service-runtime', 'pg', 'fastify', '@fastify/websocket', 'node:crypto', 'node:worker_threads'];
const privateFiles = ['apps/match-service/src/clock-service.ts', 'apps/match-service/src/clock-runner.ts', 'apps/match-service/src/clock-health.ts', 'apps/match-service/dist/clock-service.js', 'packages/db/src/clock-store.ts', 'packages/db/src/clock-types.ts', 'packages/db/dist/clock-store.js', 'packages/engine-adapter/src/clocks.ts', 'packages/engine-adapter/dist/clocks.js', 'apps/match-service/tests/clock-fixtures.mjs', 'apps/match-service/tests/clock-child.mjs'];
const forms = s => [`import x from '${s}';`, `export * from '${s}';`, `const m = await import('${s}');`, `import type { X } from '${s}';`];
let refused = 0;
for (const o of browserOwners) {
  const file = join(o.path, 'src', 'audit-virtual.ts');
  for (const target of [...privateTargets, ...privateFiles.map(f => rel(join(o.path, 'src'), join(ctx.root, f)))]) for (const code of forms(target)) {
    assert.throws(() => checkSource(file, ctx, code), /Forbidden/, o.name + ' accepted ' + code); refused++;
  }
}
checkSource(join(owner('@lorcana/match-client').path, 'src', 'audit-virtual.ts'), ctx, `import { parseClockProjection } from '@lorcana/contracts/clocks';`);
// The browser client still depends only on the closed contracts; its clock helper is a pure estimate.
const clientPkg = JSON.parse(readFileSync('packages/match-client/package.json', 'utf8'));
assert.deepEqual(clientPkg.dependencies, { '@lorcana/contracts': 'workspace:*' });
const clientSrc = readdirSync('packages/match-client/src').map(f => readFileSync('packages/match-client/src/' + f, 'utf8')).join('\n');
assert.deepEqual([...new Set([...clientSrc.matchAll(/from '([^']+)'/g)].map(m => m[1]))].sort(), ['./clocks.ts', '@lorcana/contracts', '@lorcana/contracts/clocks']);
assert.equal(/localStorage|sessionStorage|indexedDB|document\.cookie|Date\.now\(\)\s*[-+]/.test(clientSrc.replace(/grant\.expiresAt<=Date\.now\(\)\|\|grant\.sessionExpiresAt<=Date\.now\(\)/, '')), false, 'client storage/cookie/calendar-clock authority');
// Lab exposes no clock control or inspection; the kernel bundle it carries is the same pure bridge.
const labSrc = readdirSync('packages/engine-lab/src', { recursive: true }).filter(f => /\.(ts|tsx)$/.test(f)).map(f => readFileSync('packages/engine-lab/src/' + f, 'utf8')).join('\n');
assert.equal(/controlClock|\.clock\(|timeControl/.test(labSrc), false, 'Lab exposes clock control');
// Shipped browser bytes carry no server clock authority, storage, health, audit or reservation markers.
const files = dir => readdirSync(dir, { withFileTypes: true }).flatMap(e => e.isDirectory() ? files(join(dir, e.name)) : [join(dir, e.name)]);
const browserFiles = [...files('apps/web/dist'), ...files('packages/match-client/dist'), ...files('packages/engine-lab/dist')].filter(f => /\.(js|html|css|map|d\.ts)$/.test(f));
const markers = ['match.clocks', 'clock_events', 'createClockRepository', 'createClockService', 'createClockRunner', 'createClockHealth', 'sampleDatabaseUtc', 'clock_timestamp', 'reservePlayer', 'reserveTimeout', 'commitTimeout', 'unsafePause', 'recoveryAuthority', 'system-clock-timeout-v1', 'system-clock-control-v1', 'systemClockActor', 'chargeUntilUtcMs', 'lastHealthyUtcMs', 'anchorUtcMs', 'clock_charge_until', 'lorcana_match_changed', 'pg_notify', 'socket_tickets', 'private-match-checkpoint-v1', 'createMatchRepository', 'lorcana_test_match'];
for (const f of browserFiles) { const t = readFileSync(f, 'utf8'); for (const m of markers) assert.equal(t.includes(m), false, f + ' contains ' + m); }
// Every NOTIFY (old and new stores) carries only a match identifier.
const notify = [];
for (const f of ['packages/db/src/clock-store.ts', 'packages/db/src/match-store.ts', 'packages/db/src/transport-store.ts']) for (const m of readFileSync(f, 'utf8').matchAll(/pg_notify\('lorcana_match_changed',\$1\)"\s*,\s*\[([^\]]+)\]/g)) notify.push(m[1].trim());
assert.equal(notify.length, 2, "one NOTIFY in each writer store"); for (const n of notify) assert.match(n, /^(match|command)\.matchId$/, 'notify payload ' + n);
// Ordinary startup source is unchanged; diagnostics still negotiate protocol1 and register no live/clock/login route.
assert.equal(git('diff', '--name-only', MAIN, 'HEAD', '--', 'apps/match-service/src/main.ts', 'apps/api', 'apps/worker', 'packages/service-runtime/src').trim(), '');
assert.equal(/clock|gateway|live-connection|session/.test(readFileSync('apps/match-service/dist/main.js', 'utf8')), false);
const { app } = createHttpService('match-service'); await app.ready();
const routes = {}; for (const [m, u] of [['POST', '/play/ticket'], ['GET', '/play'], ['GET', '/login'], ['POST', '/clock/pause'], ['POST', '/clock/resume'], ['GET', '/clock']]) routes[m + ' ' + u] = (await app.inject({ method: m, url: u, payload: m === 'POST' ? {} : undefined })).statusCode;
const negotiated = {}; for (const offer of [{ min: 1, max: 2 }, { min: 1, max: 3 }, { min: 2, max: 3 }, { min: 3, max: 3 }]) { const r = await app.inject({ method: 'POST', url: '/protocol/negotiate', payload: { type: 'hello', requestId: 'audit', clientReleaseId: 'audit', supportedProtocol: offer } }); negotiated[offer.min + '..' + offer.max] = r.statusCode + ':' + (r.json().protocolVersion ?? r.json().code ?? r.json().type); }
await app.close();
for (const code of Object.values(routes)) assert.equal(code, 404);
assert.equal(negotiated['1..2'], '200:1'); assert.equal(negotiated['1..3'], '200:1');
// Upstream, patch set, selection, Lab and viewer/player-move contracts are byte-identical to merged main.
assert.equal(git('diff', '--name-only', MAIN, 'HEAD', '--', 'vendor/tcg-engines/upstream', 'vendor/tcg-engines/upstream.lock.json', 'vendor/tcg-engines/provenance', 'scripts/engine', 'packages/engine-lab', 'packages/contracts/src/viewer.ts', 'packages/contracts/src/player-moves.ts').trim(), '');
const bridgeFiles = git('diff', '--name-only', MAIN, 'HEAD', '--', 'vendor/').trim().split('\n');
assert.deepEqual(bridgeFiles, ['vendor/tcg-engines/README.md', 'vendor/tcg-engines/src/kernel.d.ts', 'vendor/tcg-engines/src/kernel.ts']);
const kernelSha = sha(readFileSync('vendor/tcg-engines/dist/kernel.js'));
// Public clock contract: closed, bounded, and refuses every private engine/storage field.
const good = { schemaVersion: 1, policyId: 'qualification-dynamic-v1', stateVersion: 3, clockRevision: 9, status: 'running', serverNowMs: 1000, deadlineMs: 2000, activePlayerId: 'p1', players: [{ playerId: 'p1', remainingMs: 1000 }, { playerId: 'p2', remainingMs: 150000 }], pauseReason: null };
parseClockProjection(good);
let privateFieldsRefused = 0;
for (const extra of ['engineTimestamp', 'anchorUtcMs', 'lastHealthyUtcMs', 'reservation', 'timeoutCount', 'checkpointDigest', 'seed', 'auditId', 'startedAtMs', 'policy']) { assert.throws(() => parseClockProjection({ ...good, [extra]: 1 })); privateFieldsRefused++; }
for (const extra of ['timeoutCount', 'isInNegativeTime', 'totalConsumedMs']) { assert.throws(() => parseClockProjection({ ...good, players: [{ ...good.players[0], [extra]: 1 }, good.players[1]] })); privateFieldsRefused++; }
for (const bad of [{ status: 'running', deadlineMs: null }, { status: 'paused', pauseReason: null, deadlineMs: null }, { status: 'paused', pauseReason: 'recovery' }, { activePlayerId: 'p3' }, { players: [good.players[0], good.players[0]] }, { pauseReason: 'forfeit' }, { status: 'expired' }]) assert.throws(() => parseClockProjection({ ...good, ...bad }));
for (const bad of [{ profile: 'ranked' }, { mode: 'chess' }, { graceMs: 1 }, { initialReserveMs: 0 }, { initialReserveMs: 150001 }, { resetTimeOnSkipMs: 150001 }, { extra: 1 }]) assert.throws(() => parseClockPolicy({ schemaVersion: 1, id: 'q', profile: 'qualification', mode: 'dynamic', initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0, ...bad }));
// Clients cannot send a clock: live3 client frames refuse clock/timeout/pause material.
for (const extra of [{ clock: good }, { timeout: true }, { pause: true }, { deadlineMs: 1 }]) assert.throws(() => decodeLive3ClientFrame(JSON.stringify({ type: 'command', protocolVersion: 3, matchId: 'm', commandId: 'c', correlationId: 'r', expectedStateVersion: 0, intent: { kind: 'passTurn', input: {} }, ...extra })));
// Migrations: 0001-0004 unchanged; 0005 only widens three checks and adds two match-role tables; applied in both databases.
const migrations = readdirSync('packages/db/migrations').sort();
assert.deepEqual(migrations, ['0001-foundation-probes.sql', '0002-match-commands.sql', '0003-match-receipt-invariants.sql', '0004-live-transport.sql', '0005-match-clocks.sql']);
const expected = migrations.map(name => { const b = readFileSync('packages/db/migrations/' + name); if (name < '0005') assert.equal(sha(git('show', MAIN + ':packages/db/migrations/' + name)), sha(b), name + ' changed'); return [name.slice(0, 4), sha(b)]; });
const m5 = readFileSync('packages/db/migrations/0005-match-clocks.sql', 'utf8');
const statements = m5.replace(/--[^\n]*/g, '').split(';').map(x => x.trim().replace(/\s+/g, ' ')).filter(Boolean).map(x => x.split(' (')[0].split(' ').slice(0, 6).join(' '));
assert.deepEqual(statements, ['ALTER TABLE match.matches DROP CONSTRAINT matches_protocol_version_check', 'ALTER TABLE match.matches ADD CONSTRAINT matches_protocol_version_check', 'ALTER TABLE match.socket_tickets DROP CONSTRAINT socket_tickets_protocol_version_check', 'ALTER TABLE match.socket_tickets ADD CONSTRAINT socket_tickets_protocol_version_check', 'ALTER TABLE match.command_receipts DROP CONSTRAINT command_receipts_outcome_reason', 'ALTER TABLE match.command_receipts ADD CONSTRAINT command_receipts_outcome_reason', 'CREATE TABLE match.clocks', 'CREATE TABLE match.clock_events', 'CREATE INDEX match_clock_work ON match.clocks'], '0005 statements: ' + JSON.stringify(statements));
const tables = ['releases', 'matches', 'command_receipts', 'journal', 'outbox', 'socket_tickets', 'transport_limits', 'clocks', 'clock_events'], db = {};
for (const target of ['local', 'test']) {
  const c = client(target, 'migrator'); await c.connect();
  try {
    assert.deepEqual((await c.query('SELECT id,sha256 FROM foundation.migrations ORDER BY id')).rows.map(r => [r.id, r.sha256]), expected, target + ' history');
    for (const t of tables) {
      for (const [role, all] of [['match', true], ['api', false], ['worker', false]]) {
        const p = (await c.query("SELECT has_table_privilege($1,$2,'SELECT') s, has_table_privilege($1,$2,'INSERT') i, has_table_privilege($1,$2,'UPDATE') u, has_table_privilege($1,$2,'DELETE') d", [`lorcana_${target}_${role}`, 'match.' + t])).rows[0];
        assert.deepEqual([p.s, p.i, p.u, p.d], [all, all, all, all], target + ' ' + role + ' ' + t);
      }
      assert.equal((await c.query("SELECT count(*)::int n FROM information_schema.role_table_grants WHERE table_schema='match' AND table_name=$1 AND grantee='PUBLIC'", [t])).rows[0].n, 0);
    }
    const def = async name => (await c.query('SELECT pg_get_constraintdef(oid) d FROM pg_constraint WHERE conname=$1', [name])).rows.map(r => r.d);
    db[target] = {
      migrations: (await c.query('SELECT count(*)::int n FROM foundation.migrations')).rows[0].n,
      protocolCheck: (await def('matches_protocol_version_check'))[0], ticketCheck: (await def('socket_tickets_protocol_version_check'))[0], receiptCheck: (await def('command_receipts_outcome_reason'))[0],
      clocks: (await c.query('SELECT count(*)::int n FROM match.clocks')).rows[0].n, clockEvents: (await c.query('SELECT count(*)::int n FROM match.clock_events')).rows[0].n,
      timedMatches: (await c.query('SELECT count(*)::int n FROM match.matches WHERE protocol_version=3')).rows[0].n,
    };
    assert.match(db[target].protocolCheck, /\(1\)::smallint.*\(2\)::smallint.*\(3\)::smallint|1, 2, 3/); assert.match(db[target].receiptCheck, /forbidden.*invalid_intent.*clock_expired/);
  } finally { await c.end(); }
}
console.log(JSON.stringify({ browserOwners: browserOwners.length, browserImportsRefused: refused, browserFilesScanned: browserFiles.length, markers: markers.length, notifyCalls: notify, ordinaryRoutes: routes, negotiated, implementedRange: IMPLEMENTED_PROTOCOL_RANGE, bridgeFiles, kernelSha, privateClockFieldsRefused: privateFieldsRefused, migrations: expected.map(([i, h]) => i + ':' + h.slice(0, 12)), db }));
